using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchPostTool
{
    [McpServerTool, Description("Fetches a post by ID from the external JSONPlaceholder API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to fetch (1-100).")] int postId)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"/posts/{postId}");
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var root = doc.RootElement;

        return $"""
            Post #{root.GetProperty("id")}
            Title: {root.GetProperty("title").GetString()}
            Body: {root.GetProperty("body").GetString()}
            """;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Desired output style: 'bullets', 'paragraph', or 'tldr'. Defaults to 'paragraph'.")]
        string style = "paragraph")
    {
        var instruction = style.ToLowerInvariant() switch
        {
            "bullets" => "Summarize the following text as a concise bullet-point list.",
            "tldr"    => "Provide a one-sentence TL;DR of the following text.",
            _         => "Summarize the following text in a short paragraph.",
        };

        return
        [
            new(McpServerPromptMessageRole.User, new($"{instruction}\n\n{text}")),
        ];
    }
}

